package com.hanyuflow.android;
import android.database.sqlite.SQLiteDatabase;
import android.database.Cursor;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import java.util.UUID;

public class ProgramStoreTest {
 SQLiteDatabase db;JSONObject data,curriculum;ProgramStore store;long now;
 JSONObject load(String file)throws Exception{try(java.io.InputStream in=InstrumentationRegistry.getInstrumentation().getTargetContext().getAssets().open(file)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONObject(out.toString("UTF-8"));}}
 @Before public void setup()throws Exception{data=load("program.json");curriculum=load("curriculum.json");now=java.time.Instant.parse("2026-10-13T08:00:00Z").toEpochMilli();db=SQLiteDatabase.create(null);db.execSQL("CREATE TABLE practice_points(event_id TEXT PRIMARY KEY,amount INTEGER,kind TEXT,created_at INTEGER)");db.execSQL("CREATE TABLE reviews(vocab_id TEXT PRIMARY KEY,due INTEGER)");db.execSQL("CREATE TABLE progress(lesson_id TEXT PRIMARY KEY,completed_at INTEGER)");db.execSQL("CREATE TABLE attempts(lesson_id TEXT,exercise_order INTEGER,correct INTEGER,created_at INTEGER)");ProgramStore.createTables(db);store=new ProgramStore(db,data,curriculum,()->now);}
 @After public void close(){db.close();}
 String event(){return UUID.randomUUID().toString();}
 JSONObject answer(String run,int order,Object answer,String event)throws Exception{return store.attempt(new JSONObject().put("runId",run).put("order",order).put("answer",answer).put("eventId",event));}
 JSONObject finish(String course)throws Exception{JSONObject start=store.start(course,false,"UTC");String run=start.getJSONObject("run").getString("id");JSONArray tasks=start.getJSONObject("course").getJSONArray("exercises");for(int i=0;i<tasks.length();i++)assertTrue(answer(run,i,tasks.getJSONObject(i).get("answer"),event()).getBoolean("correct"));return store.complete(run);}
 void finishAll()throws Exception{JSONArray courses=data.getJSONArray("courses");for(int i=0;i<courses.length();i++)finish(courses.getJSONObject(i).getString("id"));}
 @Test public void contentCountsAndNoLegacyMasteryBackfill()throws Exception{assertEquals(10,data.getJSONArray("courses").length());assertEquals(3,data.getJSONArray("checkForms").length());assertEquals(82,curriculum.getJSONArray("words").length());db.execSQL("INSERT INTO progress VALUES ('greetings-1',123)");assertEquals(0,store.summary("UTC").getInt("completedCourses"));assertFalse(store.summary("UTC").getBoolean("masteryConfirmed"));assertEquals(0,store.summary("UTC").getJSONObject("skills").getJSONObject("listening").getInt("total"));}
 @Test public void resumeFirstAttemptAssistanceAndIdempotentPoints()throws Exception{JSONObject p=store.start("sound-1",false,"UTC");String run=p.getJSONObject("run").getString("id");JSONArray tasks=p.getJSONObject("course").getJSONArray("exercises");String wrong=event();assertFalse(answer(run,0,"wrong",wrong).getBoolean("correct"));assertFalse(answer(run,0,"wrong",wrong).getBoolean("correct"));store=new ProgramStore(db,data,curriculum,()->now);assertEquals(run,store.start("sound-1",false,"UTC").getJSONObject("run").getString("id"));store.help(new JSONObject().put("runId",run).put("order",1).put("kind","HINT"));for(int i=0;i<tasks.length();i++)answer(run,i,tasks.getJSONObject(i).get("answer"),event());JSONObject result=store.complete(run);assertEquals(83,result.getInt("accuracy"));assertEquals(67,result.getInt("unhintedAccuracy"));assertTrue(store.complete(run).getBoolean("duplicate"));assertEquals(0,store.complete(run).getInt("points"));JSONObject repeat=store.start("sound-1",true,"UTC");assertNotEquals(run,repeat.getJSONObject("run").getString("id"));assertEquals(0,repeat.getJSONObject("run").getInt("novel"));}
 @Test public void freshRetentionCannotBeEarnedByImmediateRepeats()throws Exception{finishAll();assertFalse(store.summary("UTC").getBoolean("masteryConfirmed"));finish("check-1");try{store.start("check-2",false,"UTC");fail("early fresh followup allowed");}catch(IllegalArgumentException expected){}JSONObject reused=store.start("check-1",true,"UTC");assertEquals(0,reused.getJSONObject("run").getInt("novel"));now+=86400000L;finish("check-2");assertTrue(store.summary("UTC").getBoolean("masteryConfirmed"));}
 @Test public void preansweredResumedFormCannotBecomeDelayedRetention()throws Exception{finishAll();JSONObject second=store.start("check-2",false,"UTC");String run=second.getJSONObject("run").getString("id");JSONArray tasks=second.getJSONObject("course").getJSONArray("exercises");for(int i=0;i<tasks.length();i++)answer(run,i,tasks.getJSONObject(i).get("answer"),event());finish("check-1");now+=86400000L;assertEquals(run,store.start("check-2",false,"UTC").getJSONObject("run").getString("id"));answer(run,9,tasks.getJSONObject(9).get("answer"),event());assertEquals(100,store.complete(run).getInt("unhintedAccuracy"));assertFalse(store.summary("UTC").getBoolean("masteryConfirmed"));finish("check-3");assertTrue(store.summary("UTC").getBoolean("masteryConfirmed"));}
 @Test public void earlyExposureWithoutAnswersRemainsPracticeWhenResumedNextDay()throws Exception{finishAll();JSONObject early=store.start("check-2",false,"UTC");String run=early.getJSONObject("run").getString("id");finish("check-1");now+=86400000L;JSONObject resumed=store.start("check-2",false,"UTC");assertEquals(run,resumed.getJSONObject("run").getString("id"));JSONArray tasks=resumed.getJSONObject("course").getJSONArray("exercises");for(int i=0;i<10;i++)answer(run,i,tasks.getJSONObject(i).get("answer"),event());store.complete(run);int attempts=store.export().getJSONArray("attempts").length();store=new ProgramStore(db,data,curriculum,()->now);assertFalse(store.summary("UTC").getBoolean("masteryConfirmed"));assertEquals(attempts,store.export().getJSONArray("attempts").length());finish("check-3");assertTrue(store.summary("UTC").getBoolean("masteryConfirmed"));}
 @Test public void actualMixedCheckAcceptsDictionaryNumberPinyinButRejectsWrongTone()throws Exception{finishAll();JSONObject p=store.start("check-3",false,"UTC");String run=p.getJSONObject("run").getString("id");JSONArray tasks=p.getJSONObject("course").getJSONArray("exercises");for(int i=0;i<3;i++)answer(run,i,tasks.getJSONObject(i).get("answer"),event());assertTrue(answer(run,3,"qing3 shuo1 man4 yi1 dian3 r",event()).getBoolean("correct"));assertFalse(answer(run,3,"qing2 shuo1 man4 yi1 dian3 r",event()).getBoolean("correct"));assertTrue(answer(run,3,"qing3 shuo1 man4 yi4 dian3 r",event()).getBoolean("correct"));}
 @Test public void revealsMakeFreshScoreAssisted()throws Exception{finishAll();JSONObject p=store.start("check-1",false,"UTC");String run=p.getJSONObject("run").getString("id");JSONArray tasks=p.getJSONObject("course").getJSONArray("exercises");for(int i=0;i<3;i++)store.help(new JSONObject().put("runId",run).put("order",i).put("kind","REVEAL"));for(int i=0;i<10;i++)answer(run,i,tasks.getJSONObject(i).get("answer"),event());JSONObject result=store.complete(run);assertEquals(100,result.getInt("accuracy"));assertEquals(70,result.getInt("unhintedAccuracy"));assertFalse(result.getBoolean("passed"));assertTrue(store.summary("UTC").isNull("firstFreshPassAt"));}
 @Test public void mistakePracticeHasDueDatesNoPointsAndIdempotency()throws Exception{JSONObject p=store.start("use-1",false,"UTC");String run=p.getJSONObject("run").getString("id");answer(run,0,"wrong",event());JSONObject item=store.mistakes().getJSONArray("items").getJSONObject(0);String id=event();JSONObject in=new JSONObject().put("key",item.getString("item_key")).put("eventId",id).put("answer",item.getJSONObject("task").get("answer"));assertTrue(store.practice(in).getBoolean("correct"));assertTrue(store.practice(in).getBoolean("duplicate"));assertEquals(0,store.summary("UTC").getInt("mistakesDue"));assertEquals(0,store.export().getJSONArray("runs").getJSONObject(0).getInt("cursor")-1);now+=86400000L;assertEquals(1,store.summary("UTC").getInt("mistakesDue"));}
 @Test public void recordingIsOnlyAttemptedAndNeverPronunciationMastery()throws Exception{JSONObject r=store.recordSpeaking("我叫安娜。我是学生。",1500);assertFalse(r.getBoolean("assessed"));store.selfCheck(r.getString("id"),"SIMILAR");JSONObject summary=store.summary("UTC");assertEquals(1,summary.getJSONArray("speakingAttempts").length());assertFalse(summary.getBoolean("masteryConfirmed"));assertFalse(summary.getBoolean("pronunciationAssessed"));}
 @Test public void oldMistakesMigrateWithoutOldDataRemoval()throws Exception{db.execSQL("INSERT INTO practice_points VALUES ('lesson:greetings-1',37,'LESSON',123)");db.execSQL("INSERT INTO progress VALUES ('greetings-1',123)");db.execSQL("INSERT INTO attempts VALUES ('greetings-1',0,0,123)");ProgramStore.createTables(db);ProgramStore.migrateLegacyMistakes(db);assertEquals(1,store.mistakes().getJSONArray("items").length());try(Cursor c=db.rawQuery("SELECT amount FROM practice_points",null)){assertTrue(c.moveToFirst());assertEquals(37,c.getInt(0));}assertEquals(0,store.summary("UTC").getInt("completedCourses"));}
}
